const byId = {}, gInfo = {};
CAT.groups.forEach(g => (gInfo[g.id] = g));
CAT.badges.forEach(b => (byId[b.id] = b));
gInfo.community = { id: 'community', name: 'Community made', color: '#7E57C2', border: '#4527A0' };

const HEAD = {
  'content-type': 'application/json; charset=utf-8',
  'access-control-allow-origin': '*',
  'cache-control': 'public, max-age=3600',
};
const fail = (msg, status = 400) =>
  new Response(JSON.stringify({ error: msg }), { status, headers: { ...HEAD, 'cache-control': 'no-store' } });

// code "m<style>-<hex>": a selection in the default order, one style.
function fromMask(code) {
  const m = /^m(\d+)-([0-9a-f]+)$/i.exec(code);
  if (!m || !STYLES[+m[1]]) return null;
  const items = [];
  for (let k = 0; k < m[2].length; k++) {
    const v = parseInt(m[2][k], 16);
    for (let j = 0; j < 4; j++) {
      const b = CAT.badges[k * 4 + j];
      if (v >> j & 1 && b && !b.x) items.push({ b, style: +m[1] });
    }
  }
  // default order: group order, then catalog order inside the group
  const rank = {};
  CAT.groups.forEach((g, i) => (rank[g.id] = i));
  items.sort((a, b) => rank[a.b.g] - rank[b.b.g] || (a.b.o ?? CAT.badges.indexOf(a.b)) - (b.b.o ?? CAT.badges.indexOf(b.b)));
  return items;
}

// code "r<style>-<base64url>": the same kind of selection, written as ranges of catalog positions (much shorter).
// numbers, in order: gap from the previous range's end (or from 0), then range length - 1; each as a 7-bit varint.
function fromRanges(code) {
  const m = /^r(\d+)-([A-Za-z0-9_-]+)$/.exec(code);
  if (!m || !STYLES[+m[1]]) return null;
  const s = m[2].replace(/-/g, '+').replace(/_/g, '/');
  let bin; try { bin = atob(s + '='.repeat((4 - (s.length % 4)) % 4)); } catch (e) { return null; }
  const nums = []; let v = 0, sh = 0;
  for (let i = 0; i < bin.length; i++) { const x = bin.charCodeAt(i); v |= (x & 127) << sh; if (x & 128) sh += 7; else { nums.push(v); v = 0; sh = 0; } }
  const items = []; let last = 0;
  for (let k = 0; k + 1 < nums.length; k += 2) {
    const a = last + nums[k], z = a + nums[k + 1];
    for (let i = a; i <= z && i < CAT.badges.length; i++) if (!CAT.badges[i].x) items.push({ b: CAT.badges[i], style: +m[1] });
    last = z;
  }
  const rank = {};
  CAT.groups.forEach((g, i) => (rank[g.id] = i));
  items.sort((a, b) => rank[a.b.g] - rank[b.b.g] || (a.b.o ?? CAT.badges.indexOf(a.b)) - (b.b.o ?? CAT.badges.indexOf(b.b)));
  return items;
}

// code "x<base64url>": deflated JSON {c: another code, p: {badgeId: custom regex}}. Custom patterns replace the default ones.
async function inflate(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  const bin = atob(s + '='.repeat((4 - (s.length % 4)) % 4));
  const ds = new DecompressionStream('deflate-raw');
  const w = ds.writable.getWriter(); w.write(Uint8Array.from(bin, c => c.charCodeAt(0))).catch(() => {}); w.close().catch(() => {});
  return new Uint8Array(await new Response(ds.readable).arrayBuffer());
}
async function resolveCode(code) {
  const plain = fromMask(code) || fromRanges(code) || (await fromList(code));
  if (plain || code[0] !== 'x') return plain;
  let j;
  try { j = JSON.parse(new TextDecoder().decode(await inflate(code.slice(1)))); } catch (e) { return null; }
  if (!j || typeof j.c !== 'string' || j.c[0] === 'x') return null;
  const items = j.c ? await resolveCode(j.c) : [];
  if (!items) return null;
  if (Array.isArray(j.u)) {
    const rank = {};
    CAT.groups.forEach((g, i) => (rank[g.id] = i));
    rank.community = CAT.groups.length;
    const add = [];
    for (const u of j.u.slice(0, 200)) {
      if (!Array.isArray(u) || !/^[0-9a-f]{12}$/.test(u[0]) || typeof u[1] !== 'string' || typeof u[2] !== 'string' || !u[2] || u[2].length > 1500) continue;
      const g = typeof u[3] === 'string' && rank[u[3]] !== undefined && !['oneline', 'lang-code', 'lang-name'].includes(u[3]) ? u[3] : 'community';
      add.push({ g, pos: Number.isInteger(u[4]) && u[4] >= 0 ? u[4] : 1e6, it: { b: { id: 'com-' + u[0], g, n: u[1].slice(0, 60), p: u[2], f: '' }, style: 0, url: C_RAW + 'badges/' + u[0] + '.png' } });
    }
    // put each community badge inside its group, at the position it had in the builder
    add.sort((a, b) => rank[a.g] - rank[b.g] || a.pos - b.pos);
    for (const a of add) {
      let first = -1, last = -1;
      items.forEach((x, i) => { if (x.b.g === a.g) { if (first < 0) first = i; last = i; } });
      if (first >= 0) items.splice(first + Math.min(a.pos, last - first + 1), 0, a.it);
      else {
        let at = items.length;
        for (let i = 0; i < items.length; i++) if ((rank[items[i].b.g] ?? 0) > rank[a.g]) { at = i; break; }
        items.splice(at, 0, a.it);
      }
    }
  }
  const pats = j.p && typeof j.p === 'object' ? j.p : {};
  let n = 0;
  return items.map(it => {
    const p = pats[it.b.id];
    if (typeof p !== 'string' || !p.trim() || p.length > 2000 || ++n > 400) return it;
    return { ...it, pat: p };
  });
}

// code "o<base64url>": deflated list of numbers. First is the style, then one per badge, in order:
// catalogIndex * 32 + (0 for the pack style, or the style number + 1 for a single badge).
async function fromList(code) {
  if (code[0] !== 'o') return null;
  const s = code.slice(1).replace(/-/g, '+').replace(/_/g, '/');
  const bin = atob(s + '='.repeat((4 - (s.length % 4)) % 4));
  const bytes = Uint8Array.from(bin, c => c.charCodeAt(0));
  const ds = new DecompressionStream('deflate-raw');
  const w = ds.writable.getWriter(); w.write(bytes).catch(() => {}); w.close().catch(() => {});
  const raw = new Uint8Array(await new Response(ds.readable).arrayBuffer());
  const nums = []; let v = 0, sh = 0;
  for (const x of raw) { v |= (x & 127) << sh; if (x & 128) sh += 7; else { nums.push(v); v = 0; sh = 0; } }
  const base = nums.shift();
  if (!STYLES[base]) return null;
  const items = [];
  for (const n of nums) {
    const b = CAT.badges[Math.floor(n / 32)], o = n % 32;
    if (!b || b.x) continue;
    items.push({ b, style: o ? o - 1 : base });
  }
  return items;
}

function manifest(items) {
  const groups = [];
  items.forEach(({ b }) => { if (!groups.includes(b.g)) groups.push(b.g); });
  return {
    filters: items.map(({ b, style, pat, url }) => ({
      id: b.id, groupId: b.g, name: b.n, pattern: pat || b.p,
      imageURL: url || RAW + STYLES[style] + '/' + b.f,
      tagColor: '#00000000', borderColor: '#00000000', textColor: '#00000000',
      tagStyle: 'filled and bordered', isEnabled: true, type: 'filter',
    })),
    groups: groups.map(id => ({
      id, name: gInfo[id].name, color: gInfo[id].color,
      borderColor: gInfo[id].border || gInfo[id].color, isExpanded: true,
    })),
  };
}

// ---- community submissions ----
const b64d = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
const hex = buf => [...new Uint8Array(buf)].map(x => x.toString(16).padStart(2, '0')).join('');
const cors = req => {
  const o = req.headers.get('origin') || '';
  return {
    'access-control-allow-origin': SITE_ORIGINS.includes(o) ? o : SITE_ORIGINS[0],
    'access-control-allow-methods': 'GET, POST, OPTIONS', 'access-control-allow-headers': 'content-type', 'vary': 'origin',
  };
};
const jres = (obj, status, req) => new Response(JSON.stringify(obj), { status, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...cors(req) } });
const gh = (env, path, init = {}) => fetch('https://api.github.com/repos/' + C_OWNER + '/' + C_REPO + path, {
  ...init, headers: { authorization: 'Bearer ' + env.GITHUB_TOKEN, accept: 'application/vnd.github+json', 'user-agent': 'fr-badges-worker', 'x-github-api-version': '2022-11-28', ...(init.headers || {}) },
});
const toB64 = bytes => { let s = ''; for (let i = 0; i < bytes.length; i += 8192) s += String.fromCharCode(...bytes.subarray(i, i + 8192)); return btoa(s); };

async function submit(req, env) {
  if (!env.GITHUB_TOKEN) return jres({ error: 'Sharing is not switched on yet.' }, 503, req);
  if (env.SUBMIT_OFF) return jres({ error: 'Sharing is paused for now.' }, 503, req);
  if (!SITE_ORIGINS.includes(req.headers.get('origin') || '')) return jres({ error: 'Not allowed from this site.' }, 403, req);
  let j; try { j = await req.json(); } catch (e) { return jres({ error: 'Bad request.' }, 400, req); }
  const name = typeof j.n === 'string' ? j.n.trim() : '', pat = typeof j.p === 'string' ? j.p.trim() : '';
  const grp = typeof j.g === 'string' && gInfo[j.g] && !['oneline', 'lang-code', 'lang-name'].includes(j.g) ? j.g : 'community';
  if (!name || name.length > 40) return jres({ error: 'Give the badge a name of up to 40 letters.' }, 400, req);
  if (!pat || pat.length > 1000) return jres({ error: 'The pattern is empty or too long.' }, 400, req);
  if (/[<>]/.test(name)) return jres({ error: 'The name has characters that are not allowed.' }, 400, req);
  if (!(await tsOk(env, req, j.ts, 'badge'))) return jres({ error: 'The robot check failed. Please try again.' }, 403, req);
  const kh = typeof j.kh === 'string' && /^[0-9a-f]{64}$/.test(j.kh) ? j.kh : '';
  const u = typeof j.u === 'string' && /^[0-9a-f]{12}$/.test(j.u) ? j.u : '';
  let png; try { png = b64d(String(j.png || '')); } catch (e) { return jres({ error: 'The image is not valid.' }, 400, req); }
  if (png.length < 100 || png.length > 90000) return jres({ error: 'The image is too big. Keep it under 90 KB.' }, 400, req);
  const sig = [137, 80, 78, 71, 13, 10, 26, 10];
  if (!sig.every((x, i) => png[i] === x)) return jres({ error: 'The image must be a PNG.' }, 400, req);
  const dv = new DataView(png.buffer, png.byteOffset), w = dv.getUint32(16), h = dv.getUint32(20);
  if (h < 64 || h > 512 || w < 32 || w / h > 5.75) return jres({ error: 'The image size is outside what Nuvio shows well (height 64 to 512, width at most 5.75 times the height).' }, 400, req);
  const id = hex(await crypto.subtle.digest('SHA-256', png)).slice(0, 12);

  // 1) the image (if it exists already, that is fine)
  const put = await gh(env, '/contents/badges/' + id + '.png', { method: 'PUT', body: JSON.stringify({ message: 'Add community badge ' + id, content: toB64(png) }) });
  if (!put.ok && put.status !== 422) return jres({ error: 'Could not save the badge. Try again in a minute.' }, 502, req);
  // 2) the list (retry if two people add at the same moment)
  for (let t = 0; t < 4; t++) {
    const cur = await gh(env, '/contents/index.json');
    if (!cur.ok) return jres({ error: 'Could not save the badge. Try again in a minute.' }, 502, req);
    const meta = await cur.json();
    let list; try { list = JSON.parse(new TextDecoder().decode(b64d(meta.content.replace(/\n/g, '')))); } catch (e) { return jres({ error: 'The community list is damaged.' }, 502, req); }
    if (list.badges.some(b => b.id === id)) return jres({ id, url: C_RAW + 'badges/' + id + '.png', n: name, p: pat, g: grp, existed: true }, 200, req);
    if (list.badges.length >= 3000) return jres({ error: 'The community list is full.' }, 503, req);
    list.badges.unshift({ id, n: name, p: pat, g: grp, t: Math.floor(Date.now() / 1000), w, h, ...(kh ? { o: kh } : {}), ...(u ? { u } : {}) });
    const up = await gh(env, '/contents/index.json', { method: 'PUT', body: JSON.stringify({ message: 'List community badge ' + id, sha: meta.sha, content: toB64(new TextEncoder().encode(JSON.stringify(list))) }) });
    if (up.ok) return jres({ id, url: C_RAW + 'badges/' + id + '.png', n: name, p: pat, g: grp }, 200, req);
    if (up.status !== 409 && up.status !== 422) break;
  }
  return jres({ error: 'Could not save the badge. Try again in a minute.' }, 502, req);
}


// ---- edit, delete, likes, reports ----
const IDRE = /^[0-9a-f]{12}$/;
async function readIndex(env) {
  const cur = await gh(env, '/contents/index.json');
  if (!cur.ok) throw new Error('index');
  const meta = await cur.json();
  return { meta, list: JSON.parse(new TextDecoder().decode(b64d(meta.content.replace(/\n/g, '')))) };
}
const writeIndex = (env, meta, list, msg) => gh(env, '/contents/index.json', { method: 'PUT', body: JSON.stringify({ message: msg, sha: meta.sha, content: toB64(new TextEncoder().encode(JSON.stringify(list))) }) });
async function sha256(s) { return hex(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(s))); }
async function mayEdit(env, entry, k) {
  if (typeof k !== 'string' || k.length < 16) return false;
  if (env.ADMIN_KEY && k === env.ADMIN_KEY) return true;
  return !!entry.o && (await sha256(k)) === entry.o;
}
async function edit(req, env) {
  if (!env.GITHUB_TOKEN) return jres({ error: 'Not switched on yet.' }, 503, req);
  if (!SITE_ORIGINS.includes(req.headers.get('origin') || '')) return jres({ error: 'Not allowed from this site.' }, 403, req);
  let j; try { j = await req.json(); } catch (e) { return jres({ error: 'Bad request.' }, 400, req); }
  if (!IDRE.test(String(j.id || ''))) return jres({ error: 'Bad badge.' }, 400, req);
  let name, pat, grp;
  if (!j.del) {
    name = typeof j.n === 'string' ? j.n.trim() : ''; pat = typeof j.p === 'string' ? j.p.trim() : '';
    grp = typeof j.g === 'string' && gInfo[j.g] && !['oneline', 'lang-code', 'lang-name'].includes(j.g) ? j.g : 'community';
    if (!name || name.length > 40 || /[<>]/.test(name)) return jres({ error: 'Give the badge a name of up to 40 letters.' }, 400, req);
    if (!pat || pat.length > 1000) return jres({ error: 'The pattern is empty or too long.' }, 400, req);
  }
  for (let t = 0; t < 4; t++) {
    let idx; try { idx = await readIndex(env); } catch (e) { return jres({ error: 'Could not reach the list. Try again in a minute.' }, 502, req); }
    const i = idx.list.badges.findIndex(b => b.id === j.id);
    if (i < 0) return jres({ error: 'That badge is not in the list.' }, 404, req);
    if (!(await mayEdit(env, idx.list.badges[i], j.k))) return jres({ error: 'This browser did not make that badge, so it cannot change it.' }, 403, req);
    if (j.del) idx.list.badges.splice(i, 1); else Object.assign(idx.list.badges[i], { n: name, p: pat, g: grp });
    const up = await writeIndex(env, idx.meta, idx.list, (j.del ? 'Remove' : 'Edit') + ' community badge ' + j.id);
    if (up.ok) {
      if (j.del) { // also remove the picture (the list is already updated, so a failure here is harmless)
        try { const f = await gh(env, '/contents/badges/' + j.id + '.png'); if (f.ok) { const m = await f.json(); await gh(env, '/contents/badges/' + j.id + '.png', { method: 'DELETE', body: JSON.stringify({ message: 'Remove community badge ' + j.id, sha: m.sha }) }); } } catch (e) {}
        return jres({ ok: 1, deleted: 1 }, 200, req);
      }
      return jres({ ok: 1, id: j.id, n: name, p: pat, g: grp }, 200, req);
    }
    if (up.status !== 409 && up.status !== 422) break;
  }
  return jres({ error: 'Could not save the change. Try again in a minute.' }, 502, req);
}
// likes and reports live in a KV namespace bound as LIKES (optional)
async function stats(req, env) {
  if (!env.LIKES) return jres({ off: 1 }, 200, req);
  const s = {}; let cursor;
  for (let p = 0; p < 5; p++) {
    const r = await env.LIKES.list({ prefix: 's:', cursor });
    r.keys.forEach(k => { if (k.metadata) s[k.name.slice(2)] = [k.metadata.l || 0, k.metadata.r || 0]; });
    if (r.list_complete) break; cursor = r.cursor;
  }
  return jres({ ok: 1, s }, 200, req);
}
async function vote(req, env, kind) { // kind: 'l' like, 'r' report
  if (!env.LIKES) return jres({ off: 1 }, 200, req);
  if (!SITE_ORIGINS.includes(req.headers.get('origin') || '')) return jres({ error: 'Not allowed from this site.' }, 403, req);
  let j; try { j = await req.json(); } catch (e) { return jres({ error: 'Bad request.' }, 400, req); }
  const id = String(j.id || ''); if (!IDRE.test(id)) return jres({ error: 'Bad badge.' }, 400, req);
  const who = (await sha256((req.headers.get('cf-connecting-ip') || 'x') + '|' + id + '|' + kind)).slice(0, 20), mk = kind + ':' + id + ':' + who;
  const cur = await env.LIKES.getWithMetadata('s:' + id), m = { l: 0, r: 0, ...(cur.metadata || {}) };
  if (await env.LIKES.get(mk)) return jres({ ok: 1, dup: 1, l: m.l, r: m.r }, 200, req);
  await env.LIKES.put(mk, '1', { expirationTtl: 31536000 });
  m[kind]++;
  await env.LIKES.put('s:' + id, '', { metadata: m });
  return jres({ ok: 1, l: m.l, r: m.r }, 200, req);
}

// ---- style packs: images go up in small steps (a request may only make a few outgoing calls) ----
const MAX_PACKS = 150, MAX_FILES = 800, FILESET = new Set(CAT.badges.map(b => b.f));
async function hmac(env, s) {
  const k = await crypto.subtle.importKey('raw', new TextEncoder().encode(env.PACK_SECRET || env.GITHUB_TOKEN), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return hex(await crypto.subtle.sign('HMAC', k, new TextEncoder().encode(s))).slice(0, 32);
}
async function mkToken(env, id, count) { const p = id + '.' + (Math.floor(Date.now() / 1000) + 1800) + '.' + count; return p + '.' + await hmac(env, p); }
async function chkToken(env, t) {
  const a = String(t || '').split('.'); if (a.length !== 4 || !IDRE.test(a[0])) return null;
  const p = a.slice(0, 3).join('.'); if ((await hmac(env, p)) !== a[3] || +a[1] < Date.now() / 1000) return null;
  return { id: a[0], count: +a[2] };
}
async function packGate(req, env) {
  if (!env.GITHUB_TOKEN) return jres({ error: 'Sharing is not switched on yet.' }, 503, req);
  if (!SITE_ORIGINS.includes(req.headers.get('origin') || '')) return jres({ error: 'Not allowed from this site.' }, 403, req);
  try { return { j: await req.json() }; } catch (e) { return jres({ error: 'Bad request.' }, 400, req); }
}
const okName = n => typeof n === 'string' && n.trim() && n.trim().length <= 40 && !/[<>]/.test(n);
async function packStart(req, env) {
  const g = await packGate(req, env); if (g instanceof Response) return g; const j = g.j;
  if (env.SUBMIT_OFF) return jres({ error: 'Sharing is paused for now.' }, 503, req);
  if (!okName(j.n)) return jres({ error: 'Give the pack a name of up to 40 letters.' }, 400, req);
  if (!(j.count >= 1 && j.count <= MAX_FILES)) return jres({ error: 'A pack can hold 1 to ' + MAX_FILES + ' badges.' }, 400, req);
  if (!(await tsOk(env, req, j.ts, 'pack'))) return jres({ error: 'The robot check failed. Please try again.' }, 403, req);
  const id = hex(crypto.getRandomValues(new Uint8Array(6)));
  return jres({ ok: 1, id, token: await mkToken(env, id, j.count | 0) }, 200, req);
}
async function packBlobs(req, env) {
  const g = await packGate(req, env); if (g instanceof Response) return g; const j = g.j;
  if (!(await chkToken(env, j.token))) return jres({ error: 'This upload expired. Start again.' }, 403, req);
  const files = Array.isArray(j.files) ? j.files : [];
  if (!files.length || files.length > 30) return jres({ error: 'Too many images at once.' }, 400, req);
  const sig = [137, 80, 78, 71, 13, 10, 26, 10];
  const out = await Promise.all(files.map(async x => {
    if (!FILESET.has(x.f)) throw new Error('Unknown badge image ' + String(x.f).slice(0, 40));
    let png; try { png = b64d(String(x.png || '')); } catch (e) { throw new Error('An image is not valid.'); }
    if (png.length < 100 || png.length > 90000 || !sig.every((s, i) => png[i] === s)) throw new Error('An image is not a valid small PNG.');
    const dv = new DataView(png.buffer, png.byteOffset), w = dv.getUint32(16), h = dv.getUint32(20);
    if (h < 64 || h > 512 || w < 32 || w / h > 5.75) throw new Error('An image size is outside what Nuvio shows well.');
    const r = await gh(env, '/git/blobs', { method: 'POST', body: JSON.stringify({ content: toB64(png), encoding: 'base64' }) });
    if (!r.ok) throw new Error('Could not store an image. Try again.');
    return { f: x.f, sha: (await r.json()).sha };
  })).catch(e => e);
  if (out instanceof Error) return jres({ error: out.message }, 400, req);
  return jres({ ok: 1, shas: out }, 200, req);
}
async function readPacks(env) {
  const r = await gh(env, '/contents/packs.json');
  if (r.status === 404) return [];
  if (!r.ok) throw new Error('packs');
  const l = JSON.parse(new TextDecoder().decode(b64d((await r.json()).content.replace(/\n/g, ''))));
  return Array.isArray(l) ? l : [];
}
// one commit that changes several files at once; retries if somebody else committed in between
async function commitTree(env, build, msg) {
  for (let t = 0; t < 3; t++) {
    const ref = await gh(env, '/git/ref/heads/main'); if (!ref.ok) throw new Error('ref');
    const head = (await ref.json()).object.sha;
    const cm = await gh(env, '/git/commits/' + head); if (!cm.ok) throw new Error('commit');
    const baseTree = (await cm.json()).tree.sha;
    const tree = await build(); if (tree instanceof Response) return tree;
    const nt = await gh(env, '/git/trees', { method: 'POST', body: JSON.stringify({ base_tree: baseTree, tree }) }); if (!nt.ok) throw new Error('tree');
    const nc = await gh(env, '/git/commits', { method: 'POST', body: JSON.stringify({ message: msg, tree: (await nt.json()).sha, parents: [head] }) }); if (!nc.ok) throw new Error('newcommit');
    const up = await gh(env, '/git/refs/heads/main', { method: 'PATCH', body: JSON.stringify({ sha: (await nc.json()).sha }) });
    if (up.ok) return true;
    if (up.status !== 422 && up.status !== 409) throw new Error('ref update');
  }
  throw new Error('busy');
}
async function packFinish(req, env) {
  const g = await packGate(req, env); if (g instanceof Response) return g; const j = g.j;
  const tk = await chkToken(env, j.token); if (!tk) return jres({ error: 'This upload expired. Start again.' }, 403, req);
  if (!okName(j.n)) return jres({ error: 'Give the pack a name of up to 40 letters.' }, 400, req);
  const ids = Array.isArray(j.ids) ? j.ids : [];
  if (!ids.length || ids.length > tk.count || new Set(ids).size !== ids.length || !ids.every(i => byId[i])) return jres({ error: 'The badge list is not valid.' }, 400, req);
  const shas = j.shas && typeof j.shas === 'object' ? j.shas : {};
  if (!ids.every(i => /^[0-9a-f]{40}$/.test(String(shas[byId[i].f] || '')))) return jres({ error: 'Some images did not upload. Try again.' }, 400, req);
  const kh = typeof j.kh === 'string' && /^[0-9a-f]{64}$/.test(j.kh) ? j.kh : '';
  const u = typeof j.u === 'string' && /^[0-9a-f]{12}$/.test(j.u) ? j.u : '';
  const files = ids.map(i => byId[i].f), prev = (Array.isArray(j.prev) ? j.prev : []).filter(f => files.includes(f)).slice(0, 6);
  const name = j.n.trim(), pid = tk.id;
  const man = manifest(ids.map(i => ({ b: byId[i], style: 0, url: C_RAW + 'packs/' + pid + '/' + byId[i].f })));
  try {
    const r = await commitTree(env, async () => {
      const list = await readPacks(env);
      if (list.some(p => p.id === pid)) return jres({ error: 'That pack was already published.' }, 409, req);
      if (list.length >= MAX_PACKS) return jres({ error: 'The community has reached its pack limit for now.' }, 503, req);
      list.unshift({ id: pid, n: name, c: ids.length, t: Math.floor(Date.now() / 1000), prev, ...(kh ? { o: kh } : {}), ...(u ? { u } : {}) });
      return files.map(f => ({ path: 'packs/' + pid + '/' + f, mode: '100644', type: 'blob', sha: shas[f] }))
        .concat([{ path: 'packs/' + pid + '/badges.json', mode: '100644', type: 'blob', content: JSON.stringify(man) }, { path: 'packs.json', mode: '100644', type: 'blob', content: JSON.stringify(list) }]);
    }, 'Add style pack ' + pid);
    if (r instanceof Response) return r;
  } catch (e) { return jres({ error: 'Could not publish right now. Try again in a minute.' }, 502, req); }
  return jres({ ok: 1, id: pid, url: C_RAW + 'packs/' + pid + '/badges.json' }, 200, req);
}
async function packDelete(req, env) {
  const g = await packGate(req, env); if (g instanceof Response) return g; const j = g.j;
  if (!IDRE.test(String(j.id || ''))) return jres({ error: 'Bad pack.' }, 400, req);
  try {
    const r = await commitTree(env, async () => {
      const list = await readPacks(env), i = list.findIndex(p => p.id === j.id);
      if (i < 0) return jres({ error: 'That pack is not in the list.' }, 404, req);
      if (!(await mayEdit(env, list[i], j.k))) return jres({ error: 'This browser did not make that pack, so it cannot remove it.' }, 403, req);
      list.splice(i, 1);
      return [{ path: 'packs/' + j.id, mode: '040000', type: 'tree', sha: null }, { path: 'packs.json', mode: '100644', type: 'blob', content: JSON.stringify(list) }];
    }, 'Remove style pack ' + j.id);
    if (r instanceof Response) return r;
  } catch (e) { return jres({ error: 'Could not remove it right now. Try again in a minute.' }, 502, req); }
  return jres({ ok: 1, deleted: 1 }, 200, req);
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    const POSTS = { '/submit': submit, '/edit': edit, '/like': (r, e) => vote(r, e, 'l'), '/report': (r, e) => vote(r, e, 'r'), '/pack/start': packStart, '/pack/blobs': packBlobs, '/pack/finish': packFinish, '/pack/delete': packDelete };
    if (POSTS[url.pathname] || url.pathname === '/stats') {
      if (req.method === 'OPTIONS') return new Response(null, { headers: cors(req) });
      try {
        if (url.pathname === '/stats') return req.method === 'GET' ? await stats(req, env || {}) : jres({ error: 'Use GET.' }, 405, req);
        if (req.method !== 'POST') return jres({ error: 'Use POST.' }, 405, req);
        return await POSTS[url.pathname](req, env || {});
      } catch (e) { return jres({ error: 'Something went wrong.' }, 500, req); }
    }
    if (req.method === 'OPTIONS') return new Response(null, { headers: HEAD });
    const m = /^\/p\/([A-Za-z0-9_-]+)(?:\.json)?$/.exec(url.pathname);
    if (!m) return new Response('FR Badges pack links. Make one at https://farizmohd70.github.io/FR-Badges/make', { headers: { 'content-type': 'text/plain; charset=utf-8' } });
    try {
      await loadStyles();
      const items = await resolveCode(m[1]);
      if (!items) return fail('This pack link is not valid.');
      if (!items.length) return fail('This pack has no badges.');
      return new Response(JSON.stringify(manifest(items)), { headers: HEAD });
    } catch (e) {
      return fail('This pack link is not valid.');
    }
  },
};
